import { unlink } from "node:fs/promises";
import { join } from "node:path";
import { uploadRoot } from "./upload-storage.js";

// Only the exact storage name formats generated by this application's
// user_media upload handlers may be physically removed.
// Current: <account-uuid>-<file-uuid>.<canonical-extension>
// Legacy:  <account-uuid>-<file-uuid>-<sanitized-original-filename>
const UUID = "[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}";
const ownedFile = new RegExp(
  "^(" + UUID + ")-(" + UUID + ")(?:\\.[a-z0-9]{1,8}|-[a-z0-9._-]{1,120})$", "i"
);

export function isOwnedMediaStorageName(stored, ownerId) {
  if (typeof stored !== "string" || stored.length > 200 ||
      typeof ownerId !== "string") return false;
  const match = ownedFile.exec(stored);
  return Boolean(match && match[1].toLowerCase() === ownerId.toLowerCase());
}

/**
 * Best-effort compensation after the owner-scoped metadata DELETE commits.
 * Do not unlink a stored file if another user_media or creator_assets record
 * still references the same path. Missing files are already clean.
 *
 * The caller must pass a database reference check and catch cleanup failures;
 * metadata deletion/revocation must remain successful even if disk is offline.
 */
export async function removeDeletedMediaFile(stored, ownerId, isReferenced, root = uploadRoot) {
  if (!isOwnedMediaStorageName(stored, ownerId) ||
      typeof isReferenced !== "function") return "unrecognized";
  if (await isReferenced(stored)) return "referenced";
  try {
    await unlink(join(root, stored));
    return "removed";
  } catch (error) {
    if (error?.code === "ENOENT") return "missing";
    throw error;
  }
}
